<script setup>
import { onMounted,computed } from 'vue';import { useRoute } from 'vue-router';import { useDoctorStore } from '../../stores/doctors';import { useClinicContextStore } from '../../stores/clinicContext';import DoctorBadge from '../../components/doctors/DoctorBadge.vue';import DoctorActions from '../../components/doctors/DoctorActions.vue';import FormErrors from '../../components/ui/FormErrors.vue';
const route=useRoute(),store=useDoctorStore(),context=useClinicContextStore();const tabs=computed(()=>[['overview','Overview'],['schedule','Schedule','doctors.schedule.view'],['appointments','Appointments'],['activity','Activity'],...(context.allowed('prescriptions') ? [['prescriptions','Prescriptions','prescriptions.view']] : [])].filter(([, ,p])=>!p||context.can(p)));const load=()=>store.load(route.params.id);onMounted(load);
</script>
<template><RouterLink class="back-link" to="/app/doctors">← Doctors / Clinicians</RouterLink><p v-if="store.notice" class="clinic-trial mt-4" role="status">{{store.notice}}<button aria-label="Dismiss notification" class="ml-auto" @click="store.notice=''">×</button></p><FormErrors class="mt-4" :error="store.error"/><div v-if="store.busy" class="loading-state mt-4">Loading clinician profile...</div><div v-else-if="store.error" class="clinic-panel"><button class="btn" @click="load">Try again</button></div><template v-else-if="store.doctor"><section class="clinic-panel patient-profile-header"><span class="patient-profile-avatar doctor-avatar">{{store.doctor.first_name[0]}}{{store.doctor.last_name[0]}}</span><div><h1>{{store.doctor.full_name}}</h1><p>{{store.doctor.doctor_number}} · {{store.doctor.specialties.map(s=>s.name).join(', ')}}</p><p>{{store.doctor.branches.map(b=>b.name).join(', ')}}</p><div class="flex gap-2 mt-3"><DoctorBadge :value="store.doctor.status"/><DoctorBadge :value="store.doctor.availability"/></div></div><div class="patient-profile-actions"><RouterLink v-if="context.can('doctors.update') && store.doctor.can_manage_branches" class="btn" :to="`/app/doctors/${store.doctor.id}/edit`">Edit Doctor</RouterLink><DoctorActions :doctor="store.doctor" @changed="load"/></div></section><nav class="clinic-tabs mt-6" aria-label="Clinician profile"><RouterLink v-for="[path,label] in tabs" :key="path" :to="`/app/doctors/${store.doctor.id}/${path}`">{{label}}</RouterLink></nav><RouterView/></template></template>
